-- Independent holdout: frozen WSP-101..109 public declarations only.
-- No implementation, migration bodies or visible suites were read.
begin;
set local role postgres;
set local search_path to public, extensions;
select plan(40);
select has_column('public','messaging_wallets','balance_paise','operational wallet uses paise');
select hasnt_column('public','messaging_wallets','balance_credits','old operational credit column removed');
select hasnt_column('public','messaging_wallet_ledger','delta_credits','old ledger operational credit column removed');
select col_type_is('public','messaging_wallet_ledger','delta_paise','bigint','signed exact paise');
select is((select count(*) from public.messaging_wallets where converted_at is not null),3::bigint,'all three approved wallets converted');
select is((select count(*) from public.messaging_wallet_ledger where converted_at is not null),2::bigint,'no invented opening history');
select is((select sum(original_balance_credits)::text from public.messaging_wallets where converted_at is not null),'4500','original credits retained');
select is((select sum(original_balance_credits::numeric*conversion_paise_per_credit)::text from public.messaging_wallets where converted_at is not null),'450000','approved exact aggregate valuation');
select ok(not exists(select 1 from public.messaging_wallets where converted_at is not null and (conversion_paise_per_credit is distinct from 100 or conversion_currency is distinct from 'INR' or conversion_approval_ref is distinct from 'efff581' or currency is distinct from 'INR')),'wallet evidence fixed rate approval and currency');
select ok(not exists(select 1 from public.messaging_wallet_ledger where converted_at is not null and (conversion_paise_per_credit is distinct from 100 or conversion_currency is distinct from 'INR' or conversion_approval_ref is distinct from 'efff581' or currency is distinct from 'INR' or delta_paise::numeric is distinct from original_delta_credits::numeric*100 or balance_after_paise::numeric is distinct from original_balance_after_credits::numeric*100)),'signed scaling and null historical balance preserved');
select is((select count(distinct t) from (select converted_at t from public.messaging_wallets where converted_at is not null union all select converted_at from public.messaging_wallet_ledger where converted_at is not null) x),1::bigint,'one shared cutover instant');
select ok(not exists(select 1 from public.messaging_wallets w where w.balance_paise::numeric <> coalesce((select sum(l.delta_paise::numeric) from public.messaging_wallet_ledger l where l.tenant_id=w.tenant_id),0)),'each tenant reconciles independently');
select throws_ok($q$update public.messaging_wallets set original_balance_credits=original_balance_credits+1 where converted_at is not null$q$,null::char(5),null,'original wallet snapshot cannot change');
select throws_ok($q$update public.messaging_wallets set original_balance_credits=null,conversion_paise_per_credit=null,conversion_currency=null,conversion_approval_ref=null,converted_at=null where converted_at is not null$q$,null::char(5),null,'evidence cannot be cleared as one group');
select throws_ok($q$delete from public.messaging_wallets where converted_at is not null$q$,null::char(5),null,'converted wallet evidence cannot be deleted');
select throws_ok($q$update public.messaging_wallet_ledger set original_delta_credits=original_delta_credits+1 where converted_at is not null$q$,null::char(5),null,'converted ledger evidence remains append-only for owner');
insert into public.organizations(id,name,gym_code,status) values ('76900000-0000-4000-8000-000000000001','H76 Wallet','H76WAL','active');
insert into public.messaging_wallets(tenant_id,balance_paise,currency) values ('76900000-0000-4000-8000-000000000001',0,'INR');
select ok((select original_balance_credits is null and conversion_paise_per_credit is null and conversion_currency is null and conversion_approval_ref is null and converted_at is null from public.messaging_wallets where tenant_id='76900000-0000-4000-8000-000000000001'),'new wallet carries no converted history');
select throws_ok($q$update public.messaging_wallets set original_balance_credits=0,conversion_paise_per_credit=100,conversion_currency='INR',conversion_approval_ref='efff581',converted_at=now() where tenant_id='76900000-0000-4000-8000-000000000001'$q$,null::char(5),null,'native wallet cannot forge history through update');
select throws_ok($q$insert into public.messaging_wallet_ledger(tenant_id,delta_paise,currency,reason,original_delta_credits,conversion_paise_per_credit,conversion_currency,conversion_approval_ref,converted_at) values ('76900000-0000-4000-8000-000000000001',100,'INR','forgery',1,100,'INR','efff581',now())$q$,null::char(5),null,'new ledger cannot forge converted evidence');
insert into auth.users(id) values ('76900000-0000-4000-8000-000000000008'),('76900000-0000-4000-8000-000000000009');
insert into public.staff(id,tenant_id,user_id,role,full_name,is_active) values
 ('76900000-0000-4000-8000-000000000008','76900000-0000-4000-8000-000000000001','76900000-0000-4000-8000-000000000008','gym_owner','H76 Owner',true),
 ('76900000-0000-4000-8000-000000000009','76900000-0000-4000-8000-000000000001','76900000-0000-4000-8000-000000000009','front_desk','H76 Desk',true);
select set_config('request.jwt.claims','{"sub":"76900000-0000-4000-8000-000000000008","role":"authenticated","app_role":"gym_owner","staff_id":"76900000-0000-4000-8000-000000000008","tenant_id":"76900000-0000-4000-8000-000000000001"}',true);
set local role authenticated;
select is((public.list_notifications(null)->'wallet'),' {"balancePaise":"0","currency":"INR"}'::jsonb,'authorized real zero wallet is explicit money object');
select ok(not (public.list_notifications(null) ? 'walletBalanceCredits'),'no credit-labelled reader field survives');
set local role postgres;
select set_config('request.jwt.claims','{"sub":"76900000-0000-4000-8000-000000000009","role":"authenticated","app_role":"front_desk","staff_id":"76900000-0000-4000-8000-000000000009","tenant_id":"76900000-0000-4000-8000-000000000001"}',true);
set local role authenticated;
select is((public.list_notifications(null)->'wallet'),'null'::jsonb,'unauthorized money is unavailable never a zero wallet');
set local role postgres;
insert into auth.users(id) values ('76900000-0000-4000-8000-000000000002');
insert into public.platform_users(user_id,role,full_name,email,is_active) values ('76900000-0000-4000-8000-000000000002','super_admin','H76 Admin','h76@holdout.test',true);
select set_config('request.jwt.claims','{"sub":"76900000-0000-4000-8000-000000000002","role":"authenticated","app_role":"super_admin"}',true);
set local role authenticated;
select throws_ok($q$select public.adjust_messaging_wallet('76900000-0000-4000-8000-000000000001',1,'legacy fresh key','76900000-0000-4000-8000-000000000003')$q$,'22023'::char(5),null,'legacy fresh credit mutation refused');
select throws_ok($q$select public.adjust_messaging_wallet_paise('76900000-0000-4000-8000-000000000001',1,'USD','currency','76900000-0000-4000-8000-000000000003')$q$,'22023'::char(5),null,'other currency refused');
select lives_ok($q$do $$ declare a jsonb; b jsonb; begin
 a:=public.adjust_messaging_wallet_paise('76900000-0000-4000-8000-000000000001',9007199254740993,'INR','  large  ','76900000-0000-4000-8000-000000000003');
 if (a-ARRAY['ledgerId','tenantId','deltaPaise','currency','reason','balanceAfterPaise','createdAt'])<>'{}'::jsonb or (select count(*) from jsonb_object_keys(a))<>7 or a->>'deltaPaise'<>'9007199254740993' or a->>'balanceAfterPaise'<>'9007199254740993' or jsonb_typeof(a->'deltaPaise')<>'string' or jsonb_typeof(a->'balanceAfterPaise')<>'string' or a->>'currency'<>'INR' or a->>'reason'<>'large' then raise exception 'inexact or noncanonical result %',a; end if;
 perform public.adjust_messaging_wallet_paise('76900000-0000-4000-8000-000000000001',-1,'INR','subtract one','76900000-0000-4000-8000-000000000004');
 b:=public.adjust_messaging_wallet_paise('76900000-0000-4000-8000-000000000001',9007199254740993,'INR','large','76900000-0000-4000-8000-000000000003');
 if a<>b then raise exception 'replay lost original facts'; end if;
 end $$;$q$,'large signed movement exact seven-key strings and immutable replay');
select throws_ok($q$select public.adjust_messaging_wallet('76900000-0000-4000-8000-000000000001',9007199254740993,'large','76900000-0000-4000-8000-000000000003')$q$,'22023'::char(5),null,'native key never becomes old credit evidence');
select throws_ok($q$select public.adjust_messaging_wallet_paise('76900000-0000-4000-8000-000000000001',9007199254740992,'INR','large','76900000-0000-4000-8000-000000000003')$q$,'GL068'::char(5),null,'one-paisa difference conflicts');
select throws_ok($q$select public.adjust_messaging_wallet_paise('76900000-0000-4000-8000-000000000001',9223372036854775807,'INR','overflow','76900000-0000-4000-8000-000000000005')$q$,'22003'::char(5),null,'bigint ceiling remains actual paise boundary');
select throws_ok($q$select public.adjust_messaging_wallet_paise('76900000-0000-4000-8000-000000000001',-9223372036854775808,'INR','insufficient','76900000-0000-4000-8000-000000000005')$q$,'GL067'::char(5),null,'minimum bigint signed debit is insufficient not abs overflow');
set local role postgres;
select is((select balance_paise::text from public.messaging_wallets where tenant_id='76900000-0000-4000-8000-000000000001'),'9007199254740992','refusals never alter exact balance');
select is((select count(*) from public.messaging_wallet_ledger where tenant_id='76900000-0000-4000-8000-000000000001'),2::bigint,'replays and refusals append no movement');
select is((select count(*) from public.audit_log where tenant_id='76900000-0000-4000-8000-000000000001' and action='messaging_wallet.adjusted'),2::bigint,'two actual adjustments exactly two audits');
select ok(not exists(select 1 from public.messaging_wallet_ledger where tenant_id='76900000-0000-4000-8000-000000000001' and (original_delta_credits is not null or original_balance_after_credits is not null or conversion_paise_per_credit is not null or conversion_currency is not null or conversion_approval_ref is not null or converted_at is not null)),'native movements have no evidence');
select ok(not has_function_privilege('authenticated','app.enforce_wallet_conversion_evidence()','EXECUTE') and not has_function_privilege('service_role','app.enforce_wallet_conversion_evidence()','EXECUTE'),'evidence guard grants no bypass authority');
alter table public.audit_log add constraint h76_abort_actual_adjustment check (not (tenant_id='76900000-0000-4000-8000-000000000001'::uuid and action='messaging_wallet.adjusted' and reason='held audit refusal'));
set local role authenticated;
select throws_ok($q$select public.adjust_messaging_wallet_paise('76900000-0000-4000-8000-000000000001',1,'INR','held audit refusal','76900000-0000-4000-8000-000000000006')$q$,'23514'::char(5),null,'audit refusal aborts the actual monetary command');
set local role postgres;
select is((select balance_paise::text from public.messaging_wallets where tenant_id='76900000-0000-4000-8000-000000000001'),'9007199254740992','audit refusal rolls back wallet update');
select is((select count(*) from public.messaging_wallet_ledger where tenant_id='76900000-0000-4000-8000-000000000001'),2::bigint,'audit refusal rolls back ledger append');
update public.platform_users set is_active=false where user_id='76900000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($q$select public.adjust_messaging_wallet_paise('76900000-0000-4000-8000-000000000001',1,'INR','inactive actor','76900000-0000-4000-8000-000000000007')$q$,'42501'::char(5),null,'fresh authority rejects inactive super-admin');
select throws_ok($q$select public.adjust_messaging_wallet_paise('76900000-0000-4000-8000-000000000001',9007199254740993,'INR','large','76900000-0000-4000-8000-000000000003')$q$,'42501'::char(5),null,'replay cannot bypass current actor authority');
select throws_ok($q$select public.adjust_messaging_wallet('76900000-0000-4000-8000-000000000001',1,'old inactive actor','76900000-0000-4000-8000-000000000007')$q$,'42501'::char(5),null,'legacy facade retains authority before missing-key refusal');
set local role postgres;
select * from finish();
rollback;
